figures.script:
diagram("direction: right
(New) as n
[Ready] as r #blue
[Running] as x #mint
[Waiting] as w #amber
(Terminated) as t
n -> r : admitted
r -> x : scheduler dispatch
x -> r : time slice over
x -> w : waits for I/O
w -> r : I/O done
x -> t : exit
@0 n -> r : admit
@1.2 r -> x : dispatch
@2.4 x -> w : I/O
@3.6 w -> r : done
@4.8 r -> x : dispatch
@6 x -> t : exit
loop 8");

diagram("direction: right
[Runnable tasks] as t #blue
[Red-black tree ordered by virtual runtime] as tree #violet
[Leftmost = smallest vruntime] as left #mint
(Run it for a slice) as run
t -> tree : insert
tree -> left : pick
left -> run
run -> t : vruntime grows, re-insert
@0 t -> tree : task
@1.2 tree -> left : min
@2.4 left -> run : chosen
@3.6 run -> t : re-queued
loop 5");
